body.tpl-modern_dark { font-family: Arial, sans-serif; font-size: 11px; color: #0f172a; margin: 0; padding: 15px; background-color: #ffffff; }
.tpl-modern_dark .header-table { width: 100%; border-bottom: 2px solid {{ $accentColor ?: '#0284c7' }}; padding-bottom: 10px; margin-bottom: 15px; }
.tpl-modern_dark .company-name { font-size: 17px; font-weight: bold; color: {{ $accentColor ?: '#0369a1' }}; text-transform: uppercase; }
.tpl-modern_dark .company-address { font-size: 9px; color: {{ $accentColor ?: '#0284c7' }}; opacity: 0.85; }
.tpl-modern_dark .payslip-title { font-size: 17px; font-weight: bold; color: {{ $accentColor ?: '#0369a1' }}; text-align: right; text-transform: uppercase; }
.tpl-modern_dark .employee-info-table { width: 100%; background-color: {{ $accentColor ? $accentColor.'0A' : '#f0f9ff' }}; border: 1px solid {{ $accentColor ? $accentColor.'33' : '#bae6fd' }}; border-collapse: collapse; margin-bottom: 15px; }
.tpl-modern_dark .employee-info-table td { padding: 6px 10px; font-size: 10px; }
.tpl-modern_dark .meta-label { color: {{ $accentColor ?: '#0369a1' }}; font-weight: 600; }
.tpl-modern_dark .meta-val { font-weight: bold; color: #0f172a; }
.tpl-modern_dark .components-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
.tpl-modern_dark .components-table th { background-color: {{ $accentColor ?: '#0369a1' }}; color: #ffffff; border: 1px solid {{ $accentColor ?: '#0369a1' }}; padding: 7px; font-size: 10px; text-transform: uppercase; }
.tpl-modern_dark .components-table td { border: 1px solid {{ $accentColor ? $accentColor.'33' : '#7dd3fc' }}; padding: 6px 8px; font-size: 10px; }
.tpl-modern_dark .net-pay-box { background-color: {{ $accentColor ? $accentColor.'0D' : '#f0f9ff' }}; border: 1px solid {{ $accentColor ? $accentColor.'40' : '#7dd3fc' }}; color: #0f172a; padding: 10px 14px; margin-bottom: 15px; border-left: 4px solid {{ $accentColor ?: '#0284c7' }}; }
.tpl-modern_dark .net-amount { font-size: 15px; font-weight: bold; color: {{ $accentColor ?: '#0369a1' }}; }
.tpl-modern_dark .net-words { font-size: 9.5px; font-style: italic; text-align: right; color: {{ $accentColor ?: '#0369a1' }}; }
.tpl-modern_dark .footer-note { text-align: center; font-size: 8.5px; color: {{ $accentColor ?: '#38bdf8' }}; opacity: 0.7; margin-top: 15px; border-top: 1px solid {{ $accentColor ? $accentColor.'1F' : '#f0f9ff' }}; padding-top: 6px; }
